INSERT INTO "presets" ("id", "label", "prompt", "enabled", "sort_order", "feature", "group") VALUES
	('pod-unbox-try-on', U&'M\1edf t\00fai r\1ed3i m\1eb7c th\1eed', 'Casual UGC-style vertical phone video in a cosy, sunlit living room. A person framed from the chin down pulls the printed garment from the image out of a clear plastic mailer bag and holds it up to show the front design, then the clip cuts to them wearing it, smoothing the fabric over the print with both hands, and ends with a slow turn that shows the back. Keep the garment, its cut, colours and every printed design and text exactly as in the image; if the image shows no back, keep the back plain in the garment''s colour. Do not add any text, logos or watermarks. Natural, slightly handheld phone camera.', true, 1, 'video', 'pod'),
	('pod-hanger-reveal', U&'\00c1o tr\00ean m\00f3c r\1ed3i m\1eb7c', 'Bright, airy bedroom with an arched mirror and fresh flowers. A person framed from the neck down holds the printed garment from the image on a wooden hanger inside a clear garment bag, slides it out and holds it against their body, then the clip cuts to them wearing it: their hands present the front print, they turn around to show the back and finish in a relaxed side pose. Keep the garment, its cut, colours and every printed design and text exactly as in the image; if the image shows no back, keep the back plain in the garment''s colour. Do not add any text, logos or watermarks. Smooth, slightly handheld camera.', true, 2, 'video', 'pod'),
	('pod-mirror-selfie', U&'Selfie g\01b0\01a1ng khoe \00e1o', 'A person takes a mirror selfie in a warmly decorated home, the phone covering most of their face, wearing the printed garment from the image with relaxed jeans. They shift their weight, tug the hem, step closer so the print fills the frame, then step back into a full-length pose. Soft, warm indoor light with the decorations softly blurred behind. Keep the garment, its cut, colours and every printed design and text exactly as in the image. Do not add any text, logos or watermarks. Handheld phone camera seen in the mirror.', true, 3, 'video', 'pod'),
	('pod-street-reveal', U&'Khoe \00e1o ngo\00e0i ph\1ed1 h\1ed9i', 'Candid street-festival video in golden late-afternoon light. A smiling person wearing the printed garment from the image walks toward a friend who films on a phone, stops, holds the collar to present the front print, then turns around to show the back, with string lights, market stalls and a lively crowd softly blurred behind. Keep the garment, its cut, colours and every printed design and text exactly as in the image; if the image shows no back, keep the back plain in the garment''s colour. Do not add any text, logos or watermarks. Handheld phone camera.', true, 4, 'video', 'pod'),
	('pod-folded-stack', U&'C\1ea7m ch\1ed3ng \00e1o g\1ea5p r\1ed3i m\1eb7c', 'Bright bedroom with soft window light. A person framed from the chin down holds a neat stack of folded garments, each showing the design from the image, then the clip cuts to them wearing one: their hands brush over the print, the camera moves in on the print''s texture and ends on a relaxed full-front view. Keep the garment, its cut, colours and every printed design and text exactly as in the image. Do not add any text, logos or watermarks. Smooth, slightly handheld camera.', true, 5, 'video', 'pod'),
	('pod-print-closeup', U&'C\1eadn h\00ecnh in, tay ch\1ea1m v\1ea3i', 'Macro close-up: the camera glides slowly across the printed design of the garment from the image while fingertips brush the fabric to show its soft texture and the sharpness of the print, then pulls back to reveal the whole garment laid flat on a light wooden surface. Soft, even daylight. Show only the hands. Keep the garment, its colours and every printed design and text exactly as in the image. Do not add any text, logos or watermarks. No faces. Smooth, stable camera.', true, 6, 'video', 'pod'),
	('pod-jersey-game-day', U&'M\1eb7c jersey ng\00e0y xem \0111\1ea5u', 'Energetic game-day video outside a stadium in bright afternoon light. A fan wearing the jersey from the image cheers with friends at a tailgate, raises both arms, then turns around to show the back of the jersey as the camera follows, with colourful flags and a crowd softly blurred behind. Keep the jersey, its cut, colours, numbers and every printed design and text exactly as in the image; if the image shows no back, keep the back plain in the jersey''s colour. Do not add any text, logos or watermarks. Handheld camera with natural motion.', true, 7, 'video', 'pod'),
	('pod-beach-walk', U&'M\1eb7c \00e1o Hawaii d\1ea1o bi\1ec3n', 'Sunny beach boardwalk at golden hour. A relaxed person wearing the shirt from the image, open over a plain tee, strolls toward the camera as the fabric moves in the sea breeze, then the camera circles to a close-up of the print, with palm trees and the sea softly blurred behind. Keep the shirt, its cut, colours and every printed pattern and text exactly as in the image. Do not add any text, logos or watermarks. Smooth gimbal camera.', true, 8, 'video', 'pod'),
	('pod-mug-coffee', U&'R\00f3t c\00e0 ph\00ea v\00e0o c\1ed1c', 'The mug from the image stands on a sunny kitchen counter. Hot coffee is poured into it and steam rises, then a hand slowly turns the mug so its printed design faces the camera, ending on a close-up of the print. Warm morning light, shallow depth of field. Show only the hands. Keep the mug, its shape, colours and every printed design and text exactly as in the image. Do not add any text, logos or watermarks. No faces. Smooth, stable camera.', true, 9, 'video', 'pod'),
	('pod-tumbler-car', U&'Tumbler trong xe h\01a1i', 'Soft daylight inside a parked car. The tumbler from the image sits in the cup holder; a hand lifts it, brings it toward the camera and turns it slowly to show the whole wrap design, then sets it back down. Show only the hand. Keep the tumbler, its shape, colours and every printed design and text exactly as in the image. Do not add any text, logos or watermarks. No faces. Smooth, stable camera.', true, 10, 'video', 'pod'),
	('pod-ornament-tree', U&'Treo ornament l\00ean c\00e2y th\00f4ng', 'A hand hangs the ornament from the image on a decorated Christmas tree with warm twinkling lights. The ornament swings gently and turns to face the camera as the camera pushes in to a close-up of its design, with soft bokeh lights behind. Show only the hand. Keep the ornament, its shape, colours and every printed design and text exactly as in the image. Do not add any text, logos or watermarks. No faces. Smooth, stable camera.', true, 11, 'video', 'pod'),
	('pod-flag-porch', U&'C\1edd bay tr\01b0\1edbc hi\00ean nh\00e0', 'The flag from the image hangs from a pole on a sunny front porch and ripples in a gentle breeze. The camera slowly tilts up and pushes in until the whole design fills the frame, with a blue sky and a green lawn softly blurred behind. Keep the flag, its colours and every printed design and text exactly as in the image. Do not add any text, logos or watermarks. No people. Smooth, stable camera.', true, 12, 'video', 'pod'),
	('pod-decal-car', U&'D\00e1n decal l\00ean k\00ednh xe', 'Close-up on a clean car rear window in daylight. A hand presses the decal from the image onto the glass, smooths it with a card, then slowly peels away the clear transfer tape to reveal the finished decal, and the camera pulls back to show it on the car. Show only the hand. Keep the decal, its shape, colours and every design and text exactly as in the image. Do not add any text, logos or watermarks. No faces. Smooth, stable camera.', true, 13, 'video', 'pod'),
	('pod-poster-wall', U&'Treo tranh, poster l\00ean t\01b0\1eddng', 'A bright, modern living room in soft natural light. Two hands hang the framed poster or canvas from the image on the wall above a sofa and straighten it, then move out of frame as the camera slowly pushes in toward the artwork. Show only the hands. Keep the artwork, its frame, colours and every printed design and text exactly as in the image. Do not add any text, logos or watermarks. No faces. Smooth, stable camera.', true, 14, 'video', 'pod'),
	('pod-blanket-sofa', U&'Tr\1ea3i ch\0103n l\00ean sofa', 'A cosy living room in warm evening lamplight. Hands unfold the blanket from the image and drape it over a sofa, smoothing it so the whole design shows, then the camera glides closer over the pattern and texture. Show only the hands. Keep the blanket, its colours and every printed or woven design and text exactly as in the image. Do not add any text, logos or watermarks. No faces. Smooth, stable camera.', true, 15, 'video', 'pod'),
	('pod-cap-wear', U&'\0110\1ed9i m\0169 r\1ed3i xoay \0111\1ea7u', 'A person framed from the shoulders up picks the cap from the image off a wooden shelf, puts it on, adjusts the brim and turns their head slowly from side to side, ending on a close-up of the front design. Their face stays partly shaded under the brim. Soft daylight. Keep the cap, its shape, colours and every embroidered or printed design and text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', true, 16, 'video', 'pod'),
	('pod-jewelry-hand', U&'Trang s\1ee9c tr\00ean tay', 'Close-up of a hand and wrist in soft window light against neutral linen, wearing the bracelet or holding the necklace from the image. The hand turns slowly so the light catches the details, then the camera eases into a macro view of the pendant or charm. Show only the hand. Keep the jewellery, its shape, colours, materials and any engraved text exactly as in the image. Do not add any text, logos or watermarks. No faces. Smooth, stable camera.', true, 17, 'video', 'pod')
INSERT INTO "presets" ("id", "label", "prompt", "enabled", "sort_order", "feature", "group") VALUES
	('style-pod-hanger', U&'\00c1o treo m\00f3c g\1ed7', 'The garment hangs on a wooden hanger against a light, softly textured wall, with gentle window light and a small plant in the corner, like a cosy shop photo. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 1, 'image', 'pod'),
	('style-pod-folded', U&'\00c1o g\1ea5p x\1ebfp ch\1ed3ng', 'A neat stack of folded garments on a light wooden table, the top one showing its full printed design, in soft, even daylight. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 2, 'image', 'pod'),
	('style-pod-worn-ugc', U&'Ng\01b0\1eddi m\1eb7c ki\1ec3u UGC', 'A person wears the garment in a bright, lived-in bedroom, photographed like a casual phone snapshot from the chin down, in natural window light. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 3, 'image', 'pod'),
	('style-pod-kitchen', U&'B\00e0n b\1ebfp bu\1ed5i s\00e1ng', 'On a sunny kitchen counter in warm morning light, with a coffee pot and a plant softly blurred behind. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 4, 'image', 'pod'),
	('style-pod-christmas', U&'B\00ean c\00e2y th\00f4ng Noel', 'Beside a decorated Christmas tree with warm twinkling lights and soft bokeh, in a cosy festive living room. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 5, 'image', 'pod'),
	('style-pod-porch', U&'Tr\01b0\1edbc hi\00ean nh\00e0', 'On a sunny American front porch with a wooden railing, potted plants and a green lawn softly blurred behind. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 6, 'image', 'pod'),
	('style-pod-car', U&'Tr\00ean xe h\01a1i', 'On a clean car in daylight, on the rear window glass, the dashboard or in the cup holder, with the car softly blurred around it. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 7, 'image', 'pod'),
	('style-pod-living-wall', U&'Treo t\01b0\1eddng ph\00f2ng kh\00e1ch', 'Hung on the wall of a bright, modern living room above a sofa, in soft natural light with tasteful decor. Keep the product and any person exactly unchanged: the same shape, colours, printed details, face and outfit. Do not add any text, logos or watermarks.', true, 8, 'image', 'pod')
