-- POD templates (owner decision, 2026-11-15): each preset picker shows its presets in sections, print-on-demand products first, then products in
-- general, then the fashion-model motion templates of 0020. The 17 POD motion presets and 8 POD image styles come first in their pickers, and every
-- existing preset keeps its relative order right after them. An Admin can tag a curated example with the product it shows, which the Examples tabs
-- filter by; the keys are apps/web/src/lib/product-types.ts (product-types.test.ts keeps the check below in step with them).
ALTER TABLE "examples" ADD COLUMN "product_type" text;--> statement-breakpoint
ALTER TABLE "presets" ADD COLUMN "group" text DEFAULT 'product' NOT NULL;--> statement-breakpoint
ALTER TABLE "examples" ADD CONSTRAINT "examples_product_type_check" CHECK ("examples"."product_type" in ('tshirt', 'jersey', 'hoodie', 'hawaiian', 'polo', 'mug', 'tumbler', 'ornament', 'flag', 'decal', 'poster', 'blanket', 'cap', 'jewelry', 'shoes', 'home', 'other'));--> statement-breakpoint
ALTER TABLE "presets" ADD CONSTRAINT "presets_group_check" CHECK ("presets"."group" in ('pod', 'product', 'fashion'));--> statement-breakpoint
UPDATE "presets" SET "group" = 'fashion' WHERE "id" IN ('shoulder-sequence', 'turn-around', 'effortless-flip', 'studio-poise', 'arc-right', 'arc-left', 'smile-pose', 'step-back', 'the-approach', 'head-to-toe-shot', 'walk-right', 'walk-left', 'minimal-motion', 'doberman-gaze', 'runway-walk', 'face-rush', 'outfit-check', 'outfit-reveal', 'golden-hour-wall');--> statement-breakpoint
UPDATE "presets" SET "sort_order" = "sort_order" - (SELECT min("sort_order") FROM "presets" WHERE "feature" = 'video') + 18 WHERE "feature" = 'video';--> statement-breakpoint
UPDATE "presets" SET "sort_order" = "sort_order" - (SELECT min("sort_order") FROM "presets" WHERE "feature" = 'image') + 9 WHERE "feature" = 'image';--> statement-breakpoint
ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
ON CONFLICT ("id") DO NOTHING;
